<script setup lang="ts">
import {useProductivityStore} from '~/stores/productivity'; import type {Priority} from '~/types/domain'; const store=useProductivityStore(); const open=ref(false); const editing=ref<string|null>(null); const title=ref(''); const desc=ref(''); const priority=ref<Priority>('medium'); const goalId=ref(''); const status=ref<any>('active');
const save=()=>{if(!title.value.trim())return;if(editing.value)store.updateProject(editing.value,{title:title.value,description:desc.value,priority:priority.value,goalId:goalId.value||undefined,status:status.value});else store.addProject({title:title.value,description:desc.value,priority:priority.value,goalId:goalId.value||undefined});open.value=false;editing.value=null;title.value='';desc.value='';goalId.value=''}; const edit=(p:any)=>{editing.value=p.id;title.value=p.title;desc.value=p.description;priority.value=p.priority;goalId.value=p.goalId||'';status.value=p.status;open.value=true}; const count=(id:string)=>store.tasks.filter(t=>t.projectId===id)
</script>
<template><div class="space-y-5"><div class="flex justify-between"><div><h1 class="text-2xl font-black">پروژه‌ها</h1><p class="text-gray-500">پروژه‌ها محل جمع شدن کارها، اهداف و زمان واقعی‌اند.</p></div><UButton icon="i-lucide-plus" @click="open=true">پروژه جدید</UButton></div><div class="grid md:grid-cols-2 xl:grid-cols-3 gap-4"><UCard v-for="p in store.projects" :key="p.id"><template #header><div class="flex justify-between"><b>{{p.title}}</b><div><UButton icon="i-lucide-pencil" variant="ghost" size="xs" @click="edit(p)"/><UButton icon="i-lucide-trash-2" variant="ghost" size="xs" color="error" @click="store.deleteProject(p.id)"/></div></div></template><p class="text-sm text-gray-500 min-h-12">{{p.description}}</p><div class="mt-4 flex justify-between"><span>پیشرفت</span><b>{{store.projectEffectiveProgress(p.id)}}٪</b></div><UProgress :model-value="store.projectEffectiveProgress(p.id)" class="mt-2"/><div class="grid grid-cols-2 gap-2 mt-4"><UBadge variant="soft">{{count(p.id).filter(t=>t.status==='completed').length}}/{{count(p.id).length}} کار</UBadge><UBadge variant="soft">{{p.status}}</UBadge></div><UButton class="mt-4" block variant="soft" :to="`/tasks?project=${p.id}`">مشاهده کارهای پروژه</UButton></UCard></div><UModal v-model:open="open"><template #content><UCard><template #header>{{editing?'ویرایش پروژه':'پروژه جدید'}}</template><div class="space-y-4"><UInput v-model="title" placeholder="عنوان پروژه"/><UTextarea v-model="desc" placeholder="توضیح"/><USelect v-model="priority" :items="['low','medium','high','critical']"/><USelect v-model="goalId" :items="[{label:'بدون هدف',value:''},...store.goals.map(g=>({label:g.title,value:g.id}))]" value-key="value"/><USelect v-if="editing" v-model="status" :items="['active','paused','completed']"/><div class="flex justify-end gap-2"><UButton variant="ghost" @click="open=false">انصراف</UButton><UButton @click="save">ذخیره</UButton></div></div></UCard></template></UModal></div></template>
